/* Shona Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Tendai": "be thankful, be grateful — Shona", "Rudo": "love — Shona", "Tatenda": "we are thankful — Shona", "Nyasha": "grace, mercy — Shona", "Farai": "be happy, rejoice — Shona fara", "Chipo": "gift — Shona", "Moyo": "A very common Shona surname meaning heart.", "Mugabe": "Family name of Robert Mugabe, former president of Zimbabwe.", "Tsvangirai": "Family name of Morgan Tsvangirai, opposition leader.", "Mnangagwa": "Family name of Emmerson Mnangagwa, president of Zimbabwe."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Tendai';
console.log(lookup(q));

